reference_solution:
def repeated_group_digit_sum(s,k):
    while len(s)>k:
        pieces=[]
        for start in range(0,len(s),k):pieces.append(str(sum(int(char) for char in s[start:start+k])))
        s=''.join(pieces)
    return s

